CREATE OR REPLACE FUNCTION public.create_campaign_playtest(p_campaign_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.campaigns%ROWTYPE; gid uuid; code text; BEGIN SELECT * INTO c FROM public.campaigns WHERE id=p_campaign_id AND owner_id=auth.uid() AND status='published'; IF NOT FOUND THEN RAISE EXCEPTION 'Publie ta campagne avant le test.'; END IF; code:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)); INSERT INTO public.games(code,name,max_players,scenario,status,locked,solo,created_by) VALUES(code,'Test — '||c.name,1,'quete','waiting',true,true,auth.uid()) RETURNING id INTO gid; INSERT INTO public.game_players(game_id,user_id,display_name,role,race,speed,strength,endurance,hp,max_hp) VALUES(gid,auth.uid(),'Aventurier de test','adventurer','Humain',70,70,70,14,14); INSERT INTO public.game_campaigns(game_id,snapshot,is_test) VALUES(gid,'{}',true); PERFORM public.load_private_campaign(p_campaign_id,gid); UPDATE public.games SET status='playing',started_at=now() WHERE id=gid; RETURN jsonb_build_object('gameId',gid,'code',code); END $$;
REVOKE ALL ON FUNCTION public.create_campaign_playtest(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_campaign_playtest(uuid) TO authenticated;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.load_private_campaign(uuid,uuid)'::regprocedure) INTO def;
def:=replace(def,'NOT public.is_game_narrator(p_game_id)','NOT (public.is_game_narrator(p_game_id) OR (g.solo AND g.created_by=auth.uid() AND EXISTS(SELECT 1 FROM public.game_campaigns WHERE game_id=p_game_id AND is_test)))');
def:=replace(def,'SELECT count(*)*3 INTO budget FROM public.game_players WHERE game_id=p_game_id AND role=''adventurer'';','IF g.solo AND EXISTS(SELECT 1 FROM public.game_campaigns WHERE game_id=p_game_id AND is_test) THEN budget:=c.recommended_players*3; ELSE SELECT count(*)*3 INTO budget FROM public.game_players WHERE game_id=p_game_id AND role=''adventurer''; END IF;');
def:=replace(def,'is_test=false','is_test=game_campaigns.is_test'); EXECUTE def;
SELECT pg_get_functiondef('public.advance_private_campaign(uuid)'::regprocedure) INTO def;
def:=replace(def,'NOT public.is_game_narrator(p_game_id)','NOT (public.is_game_narrator(p_game_id) OR EXISTS(SELECT 1 FROM public.games g JOIN public.game_campaigns gc ON gc.game_id=g.id WHERE g.id=p_game_id AND g.solo AND g.created_by=auth.uid() AND gc.is_test))'); EXECUTE def;
END $$;